from ctypes import *
import platform
import sys

##
# The form of a valid function callback.
# MoCaX will expect a function callback that:
# - Takes two parameters:
#   -# A C array of double-precision floating point input values.
#   -# A C pointer to any additional/context data (@c None can be used when no additional data is required).
# - Returns a double-precision floating point result.
MOCAX_ORIGINAL_FUNCTION_DEF = CFUNCTYPE(c_double, POINTER(c_double), c_void_p)


class MOCAX_ORIGINAL_FUNCTION(Structure):
    """
    The MoCaX structure to pass callback functions metadata to the C interface.
    """

    _fields_ = [
        ("original_function_def", MOCAX_ORIGINAL_FUNCTION_DEF),
        ("dimension", c_int64),
        ("to_dimension", c_int64),
        ("to_defaultValues", POINTER(c_double)),
        ("to_defaultIndexes", POINTER(c_int64)),
        ("additional_data", c_void_p)
    ]

if platform.system() == "Windows":
    mocax_lib_filename = "mocaxc.dll"
else:
    mocax_lib_filename = "libmocaxc.so"
mocaxlib = cdll.LoadLibrary(mocax_lib_filename)

mocaxlib.mocax_allocate.restype = c_void_p
def mocax_allocate():
    return mocaxlib.mocax_allocate()

