mocaxlib.mocax_sliding_get_descriptor.argtypes = [c_void_p, POINTER(c_char_p), POINTER(c_int64)]
mocaxlib.mocax_sliding_get_descriptor.restype = c_uint32
def mocax_sliding_get_descriptor(mocax_sliding_instance, descriptor, length):
    return mocaxlib.mocax_sliding_get_descriptor(mocax_sliding_instance, descriptor, length)

mocaxlib.mocax_sliding_function_to_string.argtypes = [c_void_p, POINTER(c_char_p), POINTER(c_int64)]
mocaxlib.mocax_sliding_function_to_string.restype = c_uint32
def mocax_sliding_function_to_string(mocax_sliding_instance, descriptor, length):
    return mocaxlib.mocax_sliding_function_to_string(mocax_sliding_instance, descriptor, length)

mocaxlib.mocax_error_description.argtypes = [c_uint32]
mocaxlib.mocax_error_description.restype = c_char_p
def mocax_error_description(error_code):
    if (sys.version_info.major >= 3):
        return mocaxlib.mocax_error_description(error_code).decode()
    else:
        return mocaxlib.mocax_error_description(error_code)

mocaxlib.mocax_get_version_id.restype = c_char_p
def mocax_get_version_id():
    if (sys.version_info.major >= 3):
        return mocaxlib.mocax_get_version_id().decode()
    else:
        return mocaxlib.mocax_get_version_id()

mocaxlib.mocax_free.argtypes = [c_void_p]
def mocax_free(mocax_instance):
    return mocaxlib.mocax_free(mocax_instance)

## Information code to indicate the success of a function call.
MOCAX_I_SUCCESS = 0x00000000
## Error code to indicate that the dimensionality tested is not allowed/available.
MOCAX_E_DIMENSIONALITY_NOT_ALLOWED = 0x10100010
## Error code to indicate a dimensionality mismatch between different parameters.
MOCAX_E_DIMENSIONALITY_MISMATCH = 0x10100020
## Error code to indicate that parameters defining the domain boundaries of a dimension are incorrect. Violates the \f$X_\text{min} < X_\text{max}\f$ restriction.
MOCAX_E_X_MAX_LOWER_OR_EQUAL_THAN_X_MIN = 0x10200010
## Error code to indicate that a domain is incomplete.
MOCAX_E_INCOMPLETE_DOMAIN = 0x10200020
##  Error code to indicate that the N parameter must be equal or greater than 1. Violates the \f$N > 0\f$ restriction.
MOCAX_E_N_LOWER_THAN_1 = 0x10300010
##  Error code to indicate that the number of N values received doesn't match the expected number (given the number of subdivisions).
MOCAX_E_INVALID_NUMBER_OF_N_VALUES = 0x10300020
## Error code to indicate that error threshold must be greater than 0. Violates the \f$\epsilon > 0\f$ restriction.
MOCAX_E_ERROR_THRESHOLD_LOWER_OR_EQUAL_TO_0 = 0x10400010
## Error code to indicate that a number of special points was provided without a list of special points positions.
MOCAX_E_NO_SPECIAL_POINTS_PROVIDED = 0x10500010
## Error code to indicate that a negative number of special points was provided.
MOCAX_E_NEGATIVE_NUM_SPECIAL_POINTS_PROVIDED = 0x10500020
## Error code to indicate that special points cannot be outside the domain (x_min, x_max) or in its boundaries.
# Violates the \f$X_{\text{min}_i} < \text{special_point}_\text{i,j} < X_{\text{max}_i}\f$ restriction.
MOCAX_E_SPECIAL_POINTS_OUTSIDE_DOMAIN = 0x10500030
## Error code to indicate that two or more special points cannot be the same (resulting in a zero-width fragment).
# Violates the \f$\text{special_point}_\text{i,j} \ne \text{special_point}_\text{i,k}, \forall j,k: j \ne k\f$ restriction.
MOCAX_E_COINCIDING_SPECIAL_POINTS = 0x10500040
## Error code to indicate that the requested derivative order was not calculated during construction.
MOCAX_E_DERIVATIVE_ORDER_GREATER_THAN_BUILT = 0x10600010
## Error code to indicate that derivative order is lower than 0. Violates the \f$\text{derivative_order} \ge 0\f$ restriction.
MOCAX_E_DERIVATIVE_ORDER_LOWER_THAN_0 = 0x10600020
## Error code to indicate that a derivative identifier is not valid.
MOCAX_E_INVALID_DERIVATIVE_ID = 0x10600030
## Error code to indicate that the given descriptor exceeds the maximum allowed length.
MOCAX_E_DESCRIPTOR_TOO_LONG = 0x10700010
## Error code to indicate that a given value is out of the allowed range.
MOCAX_E_OUT_OF_RANGE = 0x10F00010
## Error code to indicate that at least one of the arguments was NULL (and it's not allowed).
MOCAX_E_NULL_ARGUMENT = 0x10F00020
## The sizes of two arrays don't match.
MOCAX_E_SIZES_MISMATCH = 0x10F00030
## Error code to indicate a memory allocation error (e.g., "out of memory" errors).
MOCAX_E_MEMORY_ALLOCATION_ERROR = 0x20100010
## Error code to indicate that the serialization version is incorrect.
MOCAX_E_INCORRECT_SERIALIZATION_VERSION = 0x30100010
## Error code to indicate that the expected serialization size is incorrect.
MOCAX_E_INCORRECT_SERIALIZATION_SIZE = 0x30100020
## Error code to indicate that serialized data integrity was compromised.
MOCAX_E_CORRUPTED_SERIALIZED_DATA = 0x30100030
## Error code to indicate that an arithmetic operation is not available between two operands.
MOCAX_E_ARITHMETIC_OPERATION_NOT_AVAILABLE = 0x40100010
## Error code to indicate that the two domains involved in an arithmetic operation don't overlap.
MOCAX_E_DOMAINS_NOT_OVERLAPPING = 0x40100020
## Error code to indicate that the number of dimensions is insufficient for the slicing operation.
MOCAX_E_INSUFFICIENT_DIMENSIONS_FOR_SLICING = 0x50100010
## Error code to indicate that a dimension cannot be removed twice.
MOCAX_E_SAME_DIMENSION_REMOVED_TWICE = 0x50100020
## Error code to indicate that an extrusion operation will cause a gap in the dimensionality.
MOCAX_E_DIMENSIONALITY_GAP = 0x50200010
## Error code to indicate that a dimension cannot be added twice.
MOCAX_E_SAME_DIMENSION_ADDED_TWICE = 0x50200020
## An attempt to use an unfinished MoCaX object has been made.
MOCAX_E_CONSTRUCTION_NOT_YET_FINISHED = 0x60100010
## An attempt to complete the construction of an already finished MoCaX object has been made.
MOCAX_E_CONSTRUCTION_ALREADY_FINISHED = 0x60100020
## An attempt to use an unstarted MoCaX object has been made.
MOCAX_E_CONSTRUCTION_NOT_YET_STARTED = 0x60100030
